(function(root){
'use strict';
const stages=[
 {title:'The first finding',intro:'You are an independent security researcher with one GPU. Hunt for bugs. Prove five of them are real.',name:'First bounty',action:'Collect bounty',reward:5000,requirements:[['Validate 5 bugs',s=>s.valid/5]]},
 {title:'Human judgment',intro:'Your first bounty funds a team. Hire security engineers to validate findings automatically and reduce false positives. The arrows adjust monthly payroll. Bigger teams cost more per hire; keep a month of costs in cash to expand.',name:'Seed round',action:'Raise seed',reward:10000,requirements:[['Validate 30 bugs',s=>s.valid/30],['Hire 2 security engineers',s=>s.engineers/2]]},
 {title:'Better tools, better signal',intro:'Rent more compute to find more bugs. Hire AI researchers to improve the Apex harness. More compute needs more engineers to keep up.',name:'Series A',action:'Raise Series A',reward:25000,requirements:[['Find 10 criticals',s=>s.critical/10],['Improve the harness to 2×',s=>s.harness/2],['Reduce false positives to 30%',s=>.30/stats(s).fp]]},
 {title:'Word gets around',intro:'Your results speak for themselves. Marketers help them travel. Publicity attracts higher-value work, funding more compute and better research.',name:'Security at scale',action:'Complete the run',reward:0,requirements:[['Validate 500 bugs',s=>s.valid/500],['Find 50 criticals',s=>s.critical/50],['Reach 60 publicity',s=>s.publicity/60],['Reduce false positives to 15%',s=>.15/stats(s).fp]]}
];
function fresh(){return {version:2,stage:0,time:0,started:false,paused:true,speed:1,ready:false,won:false,cash:0,compute:1,engineers:0,researchers:0,marketers:0,harness:1,publicity:0,found:0,queue:0,valid:0,critical:0,validCarry:0,criticalCarry:0,reviewed:0,log:[{id:0,time:0,text:stages[0].intro}],nextLog:1,insolvent:false,cashNotice:false,stepCarry:0};}
const wages={engineers:600,compute:400,researchers:900,marketers:500};
function budget(s,key){return wages[key]*Math.pow(key==='compute'?s.compute-1:s[key],1.25);}
function canIncrease(s,key){return s[key]<100&&s.cash>=stats({...s,[key]:s[key]+1}).costs;}
function stats(s){const fp=Math.max(.035,.6/(1+s.engineers*.23+(s.harness-1)*.8));const discovery=.6*Math.pow(s.compute,.85)*Math.pow(s.harness,.7);const capacity=.3+Math.pow(s.engineers,.8)*.65;const criticalChance=Math.min(.35,.06+Math.log2(s.compute)*.018+(s.harness-1)*.025);const bounty=100*(1+s.publicity/50);const costs=Object.keys(wages).reduce((sum,key)=>sum+budget(s,key),0);const valids=Math.min(discovery,capacity)*(1-fp);const income=valids*30*bounty*(1+criticalChance*4);const research=.004*Math.pow(s.researchers,.8)*Math.pow(s.compute,.18)/Math.sqrt(s.harness);const publicityRate=.1*Math.pow(s.marketers,.8)*(1-s.publicity/125);return {publicityRate,fp,discovery,capacity,criticalChance,bounty,costs,income,net:income-costs,research,valids};}
// Compare one allocation step with the current output; future values use a 30-day projection.
const marginalLabels={engineers:'validated bugs per day',compute:'findings per day',researchers:'harness strength after 30 days',marketers:'bounty per bug after 30 days'};
function marginalOutput(s,key){const a=stats(s);if(key==='engineers')return a.valids;if(key==='compute')return a.discovery;if(key==='researchers')return s.harness+a.research*30;return 1+Math.min(100,s.publicity+a.publicityRate*30)/50;}
function marginal(s,key,direction){if(!Object.hasOwn(wages,key)||![-1,1].includes(direction)||s[key]+direction<(key==='compute'?1:0)||s[key]+direction>100)return null;const before=marginalOutput(s,key),after=marginalOutput({...s,[key]:s[key]+direction},key);return (after/before-1)*100;}
function log(s,text){s.log.push({id:s.nextLog++,time:s.time,text});s.log=s.log.slice(-60);}
function check(s){if(s.won||s.ready)return;const req=stages[s.stage].requirements;if(req.every(([,f])=>f(s)>=1)){s.ready=true;s.paused=true;s.stepCarry=0;s.cashNotice=false;s.insolvent=false;log(s,stages[s.stage].name+' milestone reached.');}}
function validate(s,n){n=Math.min(n,s.queue);if(n<=0)return;const a=stats(s);s.queue-=n;s.reviewed+=n;s.validCarry+=n*(1-a.fp);const v=Math.floor(s.validCarry+1e-9);s.validCarry-=v;s.valid+=v;s.criticalCarry+=v*a.criticalChance;const c=Math.floor(s.criticalCarry+1e-9);s.criticalCarry-=c;s.critical+=c;if(s.stage>0)s.cash+=(v+c*4)*a.bounty;if(c&&s.critical===c)log(s,'Your first critical is confirmed. Critical findings earn five times the bounty.');}
function hunt(s){if(!s.started||s.paused||s.stage!==0||s.ready||s.won)return false;s.found++;s.queue++;validate(s,1);check(s);return true;}
function adjust(s,key,direction){if(![-1,1].includes(direction)||!Object.hasOwn(wages,key)||!s.started||s.ready||s.won)return false;const unlock={engineers:1,compute:2,researchers:2,marketers:3};if(s.stage<unlock[key])return false;const min=key==='compute'?1:0;if(s[key]+direction<min||s[key]+direction>100)return false;if(direction>0&&!canIncrease(s,key))return false;s[key]+=direction;check(s);return true;}
function claim(s){if(!s.ready||s.won)return false;const m=stages[s.stage];s.cash+=m.reward;s.ready=false;s.paused=true;s.speed=1;s.cashNotice=false;s.insolvent=false;s.stepCarry=0;if(s.stage===stages.length-1){s.won=true;log(s,'Security at scale. You built a company that turns compute into proven bugs.');}else{s.stage++;log(s,m.name+' closed: +$'+m.reward.toLocaleString()+'. '+stages[s.stage].intro);}return true;}
function continueSolo(s){if(!s.insolvent||s.ready||s.won)return false;s.engineers=0;s.researchers=0;s.marketers=0;s.compute=1;s.cashNotice=false;s.insolvent=false;s.paused=false;s.stepCarry=0;log(s,'You chose to cancel paid budgets and continue solo. Your own research and original GPU keep producing income.');return true;}
function step(s,days){if(!s.started||s.paused||s.ready||s.won||!Number.isFinite(days)||days<=0)return;
 // Quantize only the clock remainder to avoid floating-point drift between tick sizes.
 s.stepCarry=Math.round(((s.stepCarry||0)+Math.min(days,30))*1e12)/1e12;
 while(s.stepCarry>=.2){s.stepCarry=Math.max(0,Math.round((s.stepCarry-.2)*1e12)/1e12);s.time+=.2;if(s.stage===0)continue;const a=stats(s);s.harness+=a.research*.2;s.publicity=Math.min(100,s.publicity+a.publicityRate*.2);const n=a.discovery*.2;s.found+=n;s.queue+=n;validate(s,a.capacity*.2);s.cash-=a.costs*.2/30;
  const exhausted=s.cash<0;if(exhausted)s.cash=0;check(s);
  if(!s.ready&&exhausted){s.paused=true;s.cashNotice=true;s.insolvent=true;log(s,'Cash ran out. Game paused; your team and GPUs are still allocated. Review budgets or choose to continue solo.');}else if(!exhausted)s.insolvent=false;
  if(s.paused||s.ready||s.won){s.stepCarry=0;break;}
 }
}
function validSave(x){return x&&x.version===2&&Number.isInteger(x.stage)&&x.stage>=0&&x.stage<4&&['cash','time','harness','publicity','found','queue','valid','critical','validCarry','criticalCarry','reviewed','nextLog'].every(k=>Number.isFinite(x[k])&&x[k]>=-1e-6)&&['engineers','researchers','marketers','compute'].every(k=>Number.isInteger(x[k])&&x[k]>=(k==='compute'?1:0)&&x[k]<=100)&&(x.stepCarry===undefined||Number.isFinite(x.stepCarry)&&x.stepCarry>=0&&x.stepCarry<.2)&&(x.cashNotice===undefined||typeof x.cashNotice==='boolean')&&[1,4,16].includes(x.speed)&&Array.isArray(x.log)&&x.log.every(e=>typeof e.text==='string'&&Number.isFinite(e.time)&&Number.isInteger(e.id));}
const api={fresh,stats,budget,canIncrease,marginal,marginalLabels,stages,wages,hunt,adjust,claim,continueSolo,step,validSave};if(typeof module!=='undefined')module.exports=api;else root.CantinaGame=api;
})(typeof window!=='undefined'?window:globalThis);
